import datetime
from typing import Annotated

from pydantic import BaseModel, Field
from pydantic.functional_validators import AfterValidator

from app.domain.rider_id import normalize_rider_id


def _validate_rider_id(v: str) -> str:
    try:
        return normalize_rider_id(v)
    except Exception as e:
        raise ValueError(str(e)) from e


class MessageRequest(BaseModel):
    message_id: str = Field(..., min_length=1)
    rider_id: Annotated[str, AfterValidator(_validate_rider_id)]
    text: str = Field(..., min_length=1)
    received_at: datetime.datetime


class MessageResponse(BaseModel):
    reply: str

import logging

from fastapi import Depends, FastAPI, HTTPException
from sqlalchemy import text
from sqlalchemy.orm import Session

from app.db.session import get_db
from app.schemas.message import MessageRequest, MessageResponse
from app.services.message_service import process_message

logger = logging.getLogger(__name__)

app = FastAPI(title="QuickDrop Rider Payout Dispute Desk")


@app.get("/health")
def health(db: Session = Depends(get_db)) -> dict[str, str]:
    try:
        db.execute(text("SELECT 1"))
        return {"status": "ok", "db": "connected"}
    except Exception as e:
        logger.error(f"Healthcheck failed: {e}")
        raise HTTPException(status_code=503, detail="Service unavailable")


@app.post("/messages", response_model=MessageResponse)
def handle_message(request: MessageRequest, db: Session = Depends(get_db)) -> MessageResponse:
    try:
        reply = process_message(db, request)
        return MessageResponse(reply=reply)
    except Exception as e:
        logger.exception("Failed to process message")
        raise HTTPException(status_code=500, detail="Internal server error")

